from collections import Counter

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for row in out:
        if row and row[0] != bg:
            last = max(i for i, v in enumerate(row) if v != bg)
            for i in range(last + 1, len(row)):
                row[i] = 1
    return out
